exercise.referenceSolution:
#include <iostream>
#include <iomanip>

int scale(int value) { return value * 2; }
double scale(double value) { return value * 0.5; }
int main() {
    char tag{};
    if (!(std::cin >> tag)) return 1;
    if (tag == 'I') {
        int value{};
        if (!(std::cin >> value)) return 1;
        std::cout << scale(value) << '\n';
    } else if (tag == 'D') {
        double value{};
        if (!(std::cin >> value)) return 1;
        std::cout << std::fixed << std::setprecision(1) << scale(value) << '\n';
    } else return 1;
}
